(function () {
    'use strict';

    const ADD_MINUTES = 60;

    $p.on('change', 'StartTime', function () {
        const startControl = $p.getControl('StartTime');
        const completionControl =
            $p.getControl('CompletionTime');

        const startTime =
            parseDateTime(startControl.val());

        // 開始予定日時が空欄または不正なら何もしない
        if (!startTime) {
            return;
        }

        const completionValue =
            completionControl.val();

        const completionTime =
            parseDateTime(completionValue);

        // 終了予定日時が入力済みで、
        // 開始予定日時より早くなければ上書きしない
        if (
            completionValue &&
            completionTime &&
            completionTime >= startTime
        ) {
            return;
        }

        // 空欄または開始予定日時より早い場合
        const newCompletionTime = new Date(
            startTime.getTime() +
                ADD_MINUTES * 60 * 1000
        );

        $p.set(
            completionControl,
            formatDateTime(newCompletionTime)
        );
    });

    function parseDateTime(value) {
        const match = String(value || '')
            .trim()
            .match(
                /^(\d{4})[\/-](\d{1,2})[\/-](\d{1,2})(?:[ T](\d{1,2}):(\d{2})(?::(\d{2}))?)?$/
            );

        if (!match) {
            return null;
        }

        const year = Number(match[1]);
        const month = Number(match[2]);
        const day = Number(match[3]);
        const hour = Number(match[4] || 0);
        const minute = Number(match[5] || 0);
        const second = Number(match[6] || 0);

        const date = new Date(
            year,
            month - 1,
            day,
            hour,
            minute,
            second
        );

        // 2月30日などの不正な日時を除外
        if (
            date.getFullYear() !== year ||
            date.getMonth() !== month - 1 ||
            date.getDate() !== day ||
            date.getHours() !== hour ||
            date.getMinutes() !== minute ||
            date.getSeconds() !== second
        ) {
            return null;
        }

        return date;
    }

    function formatDateTime(date) {
        return (
            date.getFullYear() +
            '/' +
            pad(date.getMonth() + 1) +
            '/' +
            pad(date.getDate()) +
            ' ' +
            pad(date.getHours()) +
            ':' +
            pad(date.getMinutes())
        );
    }

    function pad(value) {
        return String(value).padStart(2, '0');
    }
})();

(function () {
    'use strict';

    const BULK_COPY_CONTROL_ID = 'TaskBulkCopyCommand';
    const CREATE_RECURRING_CONTROL_ID = 'CreateRecurringTasksCommand';
    const REFRESH_CONTROL_ID = 'TaskCommandsRefreshCommand';

    // ボタン色
    if ($('#TaskCommandButtonStyles').length === 0) {
        $('<style/>', {
            id: 'TaskCommandButtonStyles',
            text: `
                /* 選択タスクを一括コピー：オレンジ */
                #TaskBulkCopyCommand {
                    background: #ef6c00 !important;
                    border-color: #e65100 !important;
                    color: #ffffff !important;
                }

                #TaskBulkCopyCommand:hover {
                    background: #e65100 !important;
                    border-color: #bf360c !important;
                }

                /* 本日の定例タスクを作成：緑 */
                #CreateRecurringTasksCommand {
                    background: #2e7d32 !important;
                    border-color: #1b5e20 !important;
                    color: #ffffff !important;
                }

                #CreateRecurringTasksCommand:hover {
                    background: #1b5e20 !important;
                    border-color: #124116 !important;
                }
            `
        }).appendTo('head');
    }

    const $commands = $('#MainCommands');
    if ($commands.length === 0) {
        return;
    }

    let running = false;

    const $bulkCopyButton = createCommandButton(
        BULK_COPY_CONTROL_ID,
        '選択タスクを一括コピー',
        '選択したタスクを、新しいタスクとして一括コピーします。よろしいですか？'
    );

    const $createRecurringButton = createCommandButton(
        CREATE_RECURRING_CONTROL_ID,
        '本日の定例タスクを作成',
        '定例タスクマスタから、本日のタスクを一括作成します。よろしいですか？'
    );

    const $refreshButton = $('<button/>', {
        id: REFRESH_CONTROL_ID,
        type: 'button'
    })
        .attr('data-action', 'GridRows')
        .attr('data-method', 'post')
        .addClass('hidden')
        .hide();

    $commands.append($bulkCopyButton, $createRecurringButton, $refreshButton);

    $p.events['ajax_after_done_' + BULK_COPY_CONTROL_ID] = refreshGrid;
    $p.events['ajax_after_done_' + CREATE_RECURRING_CONTROL_ID] = refreshGrid;
    $p.events['ajax_after_always_' + BULK_COPY_CONTROL_ID] = resetOnFailure;
    $p.events['ajax_after_always_' + CREATE_RECURRING_CONTROL_ID] = resetOnFailure;
    $p.events['ajax_after_always_' + REFRESH_CONTROL_ID] = function () {
        running = false;
    };

    function createCommandButton(id, text, confirmationMessage) {
        return $('<button/>', {
            id: id,
            type: 'button',
            text: text,
            title: text
        })
            .attr('data-action', 'GridRows')
            .attr('data-method', 'post')
            .addClass('button button-icon button-positive')
            .on('click', function () {
                if (running) {
                    return;
                }
                if (!window.confirm(confirmationMessage)) {
                    return;
                }
                running = true;
                const result = $p.send($(this));
                if (result === false) {
                    running = false;
                }
            });
    }

    function refreshGrid() {
        window.setTimeout(function () {
            $p.send($refreshButton, undefined, true, false);
        }, 0);
    }

    function resetOnFailure(args) {
        if (args.ret !== 0) {
            running = false;
        }
    }
})();

(function () {
    'use strict';

    const targetViewId = '2';
    let handledCalendar = null;

    function moveToTodayOnce() {
        const viewSelector =
            document.getElementById('ViewSelector');

        if (
            !viewSelector ||
            String(viewSelector.value) !== targetViewId
        ) {
            handledCalendar = null;
            return;
        }

        const calendar =
            document.getElementById('FullCalendar');

        const todayButton =
            calendar &&
            calendar.querySelector('.fc-today-button');

        if (
            !calendar ||
            !todayButton ||
            handledCalendar === calendar
        ) {
            return;
        }

        // このカレンダーでは一度だけ実行
        handledCalendar = calendar;

        if (!todayButton.disabled) {
            todayButton.click();
        }
    }

    document.addEventListener('change', function (event) {
        if (event.target.id === 'ViewSelector') {
            handledCalendar = null;
            window.setTimeout(moveToTodayOnce, 0);
        }
    });

    const observer = new MutationObserver(function () {
        moveToTodayOnce();
    });

    observer.observe(document.body, {
        childList: true,
        subtree: true
    });

    window.setTimeout(moveToTodayOnce, 0);
})();

(function () {
    'use strict';
    if (window.taskGridTimerInstalled) return;
    window.taskGridTimerInstalled = true;
    const refreshId = 'TaskGridTimerRefreshCommand';
    let busy = false;
    function message(text, error) {
        let box = document.getElementById('TaskGridTimerMessage');
        if (!box) {
            box = document.createElement('div');
            box.id = 'TaskGridTimerMessage';
            box.setAttribute('role', 'status');
            box.setAttribute('aria-live', 'polite');
            const grid = document.getElementById('Grid');
            if (grid) grid.parentNode.insertBefore(box, grid);
            else document.getElementById('MainForm').prepend(box);
        }
        box.className = error ? 'task-timer-message task-timer-error' : 'task-timer-message';
        box.textContent = text;
    }
    function lock(value) {
        busy = value;
        document.querySelectorAll('.task-timer-button').forEach(function (button) {
            button.disabled = value;
        });
    }
    function refresh(text, error) {
        message(text, error);
        let control = $('#' + refreshId);
        if (!control.length) {
            control = $('<button/>', { id: refreshId, type: 'button' })
                .attr('data-action', 'GridRows').attr('data-method', 'post').hide()
                .appendTo('#MainForm');
        }
        const scroll = { x: window.scrollX, y: window.scrollY };
        let settled = false;
        const watchdog = window.setTimeout(function () {
            if (!settled) {
                message(text + ' 一覧の再取得が完了しません。再読み込みして結果を確認してください。', true);
                // Keep controls locked: never blindly repeat a possibly successful update.
            }
        }, 30000);
        $p.events['ajax_after_done_' + refreshId] = function (args) {
            if (args.ret !== 0) return;
            settled = true;
            window.clearTimeout(watchdog);
            lock(false);
            message(text, error);
            window.scrollTo(scroll.x, scroll.y);
        };
        $p.events['ajax_after_always_' + refreshId] = function (args) {
            if (args.ret !== 0 && !settled) {
                settled = true;
                window.clearTimeout(watchdog);
                message(text + ' 一覧を再読み込みして結果を確認してください。', true);
            }
        };
        if ($p.send(control, 'MainForm', true, false) === false) {
            settled = true;
            window.clearTimeout(watchdog);
            message(text + ' 一覧を再読み込みして結果を確認してください。', true);
        }
    }
    // Capture phase prevents the normal row-click navigation before it reaches jQuery.
    document.addEventListener('click', function (event) {
        const button = event.target.closest && event.target.closest('.task-timer-button');
        if (!button) return;
        event.preventDefault();
        event.stopImmediatePropagation();
        if (busy || button.disabled) return;
        if ($p.formChanged || String($('#EditOnGrid').val() || '0') !== '0') {
            message('編集内容を保存し、一覧の編集モードを終了してから操作してください。', true);
            return;
        }
        const id = Number(button.dataset.recordId);
        const siteId = Number(button.dataset.siteId);
        const processId = Number(button.dataset.processId);
        const stamp = Number(button.dataset.stamp);
        if (!(id > 0) || !(siteId > 0) || !isFinite(stamp) ||
            (processId !== 1 && processId !== 4)) return;
        const row = button.closest('tr');
        const title = row && row.querySelector('[data-name="Title"], .grid-title');
        const name = title ? title.textContent.trim() : 'ID ' + id;
        if (processId === 4 && !window.confirm('「' + name + '」の計測を終了し、タスクを完了にしますか？')) return;
        lock(true);
        button.textContent = '処理中…';
        message('ID ' + id + ' を更新しています。');
        let completed = false;
        const watchdog = window.setTimeout(function () {
            if (!completed) message('応答を確認できません。連続操作せず、一覧を再読み込みして結果を確認してください。', true);
        }, 30000);
        function finish(text, error) {
            if (completed) return;
            completed = true;
            window.clearTimeout(watchdog);
            refresh(text, error);
        }
        try {
            $p.apiUpdate({
                id: id,
                data: {
                    ApiVersion: 1.1,
                    ProcessId: processId,
                    TaskGridTimer: { SiteId: siteId, Stamp: stamp }
                },
                done: function (result) {
                    if (result && Number(result.StatusCode) === 200) {
                        finish('ID ' + id + (processId === 1 ? ' の計測を開始しました。' : ' を終了し、完了にしました。') +
                            ' 現在の絞り込み条件によっては一覧から非表示になります。', false);
                    } else {
                        finish('更新できませんでした。' + ((result && result.Message) || '最新の状態と権限を確認してください。'), true);
                    }
                },
                fail: function (xhr) {
                    const detail = xhr && xhr.responseJSON && xhr.responseJSON.Message;
                    finish(detail || '更新結果を確認できません。一覧の最新状態を確認してください（自動再送はしません）。', true);
                }
            });
        } catch (e) {
            finish('計測操作でエラーが発生しました。一覧の最新状態を確認してください。', true);
        }
    }, true);
})();

