(function () {
    'use strict';

    // 設計書 01_サイト構成から設定
    const TASK_SITE_ID = Number(context.SiteId);
    // 一覧画面の一括処理コマンドと、対象のプロセスID
    const CONTROL_ID = 'BulkProcessCommand';
    const PROCESS_ID = '6';
    const MAX_COPY_COUNT = 50;

    // 通常の一覧表示では何もせず終了する
    if (context.ControlId !== CONTROL_ID) {
        return;
    }

    let bulkProcessingItems;
    try {
        bulkProcessingItems = context.Forms.Item.get('BulkProcessingItems');
    } catch (e) {
        context.AddMessage('一括コピーのプロセスIDを取得できません。', 'alert-error');
        context.Log(e.stack || String(e));
        return;
    }

    // 一覧画面で「一括コピー」（プロセスID 6）が実行された場合だけ処理する
    if (String(bulkProcessingItems) !== PROCESS_ID) {
        return;
    }

    const selectedIds = [];
    for (const selectedId of grid.SelectedIds()) {
        selectedIds.push(Number(selectedId));
    }

    if (selectedIds.length === 0) {
        context.AddMessage('コピーするタスクを選択してください。');
        return;
    }

    if (selectedIds.length > MAX_COPY_COUNT) {
        context.Error(
            '一度にコピーできる件数は' + MAX_COPY_COUNT + '件までです。選択件数：' + selectedIds.length
        );
        return;
    }

    let successCount = 0;
    const failedIds = [];
    const copyStartTime = new Date();
    const copyCompletionTime = new Date(copyStartTime.getTime() + 60 * 60 * 1000);

    for (const selectedId of selectedIds) {
        try {
            const source = firstOrNull(items.Get(selectedId));
            if (!source) {
                failedIds.push(selectedId);
                context.Log('一括コピー：元タスクを取得できません。ID=' + selectedId);
                continue;
            }

            const target = items.NewIssue();

            // タスクの定義情報だけを引き継ぐ。「- コピー」は付与しない
            target.Title = source.Title;
            target.StartTime = new Date(copyStartTime.getTime());
            target.CompletionTime = new Date(copyCompletionTime.getTime());
            target.Body = source.Body;
            target.ClassA = source.ClassA;
            target.CheckA = source.CheckA;
            target.Owner = source.Owner;

            // 実績・自動生成情報は必ず初期化する
            target.DateA = null;
            target.DateB = null;
            target.DateC = null;
            target.DateD = null;
            target.NumA = null;
            target.NumB = null;
            target.ClassB = '';
            target.ClassC = '';
            target.CheckB = false;

            // 新規タスクの状況は必ず「開始前」にする
            target.Status = 100;

            if (items.Create(TASK_SITE_ID, target)) {
                successCount += 1;
                context.Log(
                    '一括コピー：作成成功。元ID=' + selectedId + ' 新ID=' + target.IssueId
                );
            } else {
                failedIds.push(selectedId);
                context.Log('一括コピー：作成失敗。元ID=' + selectedId);
            }
        } catch (e) {
            failedIds.push(selectedId);
            context.AddMessage(
                '一括コピーでエラーが発生しました。元ID=' + selectedId,
                'alert-error'
            );
            context.Log('一括コピー：例外。元ID=' + selectedId + ' 詳細=' + String(e));
            context.Log(e.stack || String(e));
        }
    }

    let message = 'タスクを' + successCount + '件コピーしました。';
    if (failedIds.length > 0) {
        message += ' 失敗ID：' + failedIds.join(', ');
    }
    context.AddMessage(message);

    function firstOrNull(sequence) {
        if (!sequence) {
            return null;
        }
        for (const value of sequence) {
            return value;
        }
        return null;
    }
})();

(function () {
    'use strict';
    // @siteid list start@
    const TASK_SITE_ID = Number(context.SiteId);
    const RECURRING_MASTER_SITE_ID = 9750;
    // @siteid list end@
    const BULK_COPY_CONTROL_ID = 'TaskBulkCopyCommand';
    const CREATE_RECURRING_CONTROL_ID = 'CreateRecurringTasksCommand';
    const MAX_COPY_COUNT = 50;
    const MAX_MASTER_COUNT = 50;
    const DEFAULT_DURATION_MINUTES = 60;

    if (context.ControlId === BULK_COPY_CONTROL_ID) {
        bulkCopySelectedTasks();
        return;
    }

    if (context.ControlId === CREATE_RECURRING_CONTROL_ID) {
        createTodayRecurringTasks();
    }

    function bulkCopySelectedTasks() {
        const selectedIds = [];
        for (const selectedId of grid.SelectedIds()) {
            selectedIds.push(Number(selectedId));
        }

        if (selectedIds.length === 0) {
            context.AddMessage('コピーするタスクを選択してください。', 'alert-error');
            return;
        }

        if (selectedIds.length > MAX_COPY_COUNT) {
            context.AddMessage(
                '一度にコピーできる件数は' + MAX_COPY_COUNT + '件までです。選択件数：' + selectedIds.length,
                'alert-error'
            );
            return;
        }

        let successCount = 0;
        const failedIds = [];
        const copyStartTime = new Date();
        const copyCompletionTime = new Date(
            copyStartTime.getTime() + DEFAULT_DURATION_MINUTES * 60 * 1000
        );

        for (const selectedId of selectedIds) {
            try {
                const source = firstOrNull(items.Get(selectedId));
                if (!source) {
                    failedIds.push(selectedId);
                    context.Log('一括コピー：元タスクを取得できません。ID=' + selectedId);
                    continue;
                }

                const target = items.NewIssue();
                target.Title = source.Title;
                target.StartTime = new Date(copyStartTime.getTime());
                target.CompletionTime = new Date(copyCompletionTime.getTime());
                target.Body = source.Body;
                target.ClassA = source.ClassA;
                target.CheckA = source.CheckA;
                if (Number(source.Owner) > 0) {
                    target.Owner = Number(source.Owner);
                }

                clearActualAndGenerationFields(target);
                target.Status = 100;

                if (items.Create(TASK_SITE_ID, target)) {
                    successCount += 1;
                    context.Log(
                        '一括コピー：作成成功。元ID=' + selectedId + ' 新ID=' + target.IssueId
                    );
                }
                else {
                    failedIds.push(selectedId);
                    context.Log('一括コピー：作成失敗。元ID=' + selectedId);
                }
            }
            catch (e) {
                failedIds.push(selectedId);
                context.Log(
                    '一括コピー：例外。元ID=' + selectedId + ' 詳細=' + String(e)
                );
                context.Log(e.stack || String(e));
            }
        }

        let message = 'タスクを' + successCount + '件コピーしました。';
        if (failedIds.length > 0) {
            message += ' 失敗ID：' + failedIds.join(', ');
        }
        context.AddMessage(
            message,
            failedIds.length > 0 ? 'alert-error' : 'alert-information'
        );
    }

    function createTodayRecurringTasks() {
        const activeView = {
            View: {
                ColumnFilterHash: {
                    CheckA: '1'
                },
                ColumnSorterHash: {
                    ClassB: 'asc',
                    ResultId: 'asc'
                }
            }
        };

        const activeCount = Number(
            items.Count(RECURRING_MASTER_SITE_ID, JSON.stringify(activeView))
        );
        if (activeCount > MAX_MASTER_COUNT) {
            context.AddMessage(
                '有効な定例タスクは' + MAX_MASTER_COUNT + '件以内にしてください。現在：' + activeCount + '件',
                'alert-error'
            );
            return;
        }

        activeView.PageSize = MAX_MASTER_COUNT;
        const masterRecords = items.Get(
            RECURRING_MASTER_SITE_ID,
            JSON.stringify(activeView)
        ) || [];

        const today = new Date(utilities.Today());
        const todayKey = formatDateKey(today);
        const weekday = String(today.getDay());
        const candidates = [];
        const validationErrors = [];
        let excludedCount = 0;

        for (const source of masterRecords) {
            const masterId = Number(source.ResultId);
            if (!isApplicableDate(source, todayKey) || !isApplicableWeekday(source.ClassC, weekday)) {
                excludedCount += 1;
                continue;
            }

            const title = String(source.Title || '').trim();
            const time = parseTime(source.ClassB);
            const duration = Number(source.NumA);

            if (!masterId) {
                validationErrors.push('マスタIDを取得できないレコードがあります。');
                continue;
            }
            if (!title) {
                validationErrors.push('ID ' + masterId + '：タスク名が空です。');
                continue;
            }
            if (!time) {
                validationErrors.push('ID ' + masterId + '：開始時刻はHH:mm形式で入力してください。');
                continue;
            }
            if (!isFinite(duration) || duration < 1 || Math.floor(duration) !== duration) {
                validationErrors.push('ID ' + masterId + '：所要時間は1以上の整数で入力してください。');
                continue;
            }

            candidates.push({
                source: source,
                masterId: masterId,
                title: title,
                hour: time.hour,
                minute: time.minute,
                duration: duration
            });
        }

        if (validationErrors.length > 0) {
            context.AddMessage(
                '定例タスクマスタに入力エラーがあります。タスクは作成していません。 ' +
                    validationErrors.join(' / '),
                'alert-error'
            );
            return;
        }

        let createdCount = 0;
        let skippedCount = 0;
        const failedIds = [];

        for (const candidate of candidates) {
            const generationKey = 'RECUR:' + todayKey + ':' + candidate.masterId;

            if (generationKeyExists(generationKey)) {
                skippedCount += 1;
                continue;
            }

            try {
                const source = candidate.source;
                const startTime = new Date(today.getTime());
                startTime.setHours(candidate.hour, candidate.minute, 0, 0);
                const completionTime = new Date(
                    startTime.getTime() + candidate.duration * 60 * 1000
                );

                const target = items.NewIssue();
                target.Title = candidate.title;
                target.StartTime = startTime;
                target.CompletionTime = completionTime;
                target.Body = source.Body;
                target.ClassA = source.ClassA;
                target.CheckA = String(source.ClassA || '').trim() !== '';
                if (Number(source.Owner) > 0) {
                    target.Owner = Number(source.Owner);
                }

                clearActualAndGenerationFields(target);
                target.ClassB = generationKey;
                target.ClassC = String(candidate.masterId);
                target.CheckB = true;
                target.Status = 100;

                if (items.Create(TASK_SITE_ID, target)) {
                    createdCount += 1;
                    context.Log(
                        '定例タスク生成：作成成功。マスタID=' +
                            candidate.masterId +
                            ' 新ID=' +
                            target.IssueId +
                            ' 生成キー=' +
                            generationKey
                    );
                }
                else {
                    failedIds.push(candidate.masterId);
                    context.Log(
                        '定例タスク生成：作成失敗。マスタID=' + candidate.masterId
                    );
                }
            }
            catch (e) {
                failedIds.push(candidate.masterId);
                context.Log(
                    '定例タスク生成：例外。マスタID=' +
                        candidate.masterId +
                        ' 詳細=' +
                        String(e)
                );
                context.Log(e.stack || String(e));
            }
        }

        let message =
            '本日の定例タスク：作成' +
            createdCount +
            '件、作成済みのためスキップ' +
            skippedCount +
            '件、曜日・期間対象外' +
            excludedCount +
            '件。';
        if (failedIds.length > 0) {
            message += ' 作成失敗マスタID：' + failedIds.join(', ');
        }
        context.AddMessage(
            message,
            failedIds.length > 0 ? 'alert-error' : 'alert-information'
        );
    }

    function clearActualAndGenerationFields(target) {
        target.DateA = null;
        target.DateB = null;
        target.DateC = null;
        target.DateD = null;
        target.NumA = null;
        target.NumB = null;
        target.ClassB = '';
        target.ClassC = '';
        target.CheckB = false;
    }

    function generationKeyExists(generationKey) {
        const request = {
            PageSize: 1,
            View: {
                ColumnFilterHash: {
                    ClassB: generationKey
                },
                ColumnFilterSearchTypes: {
                    ClassB: 'ExactMatch'
                }
            }
        };
        const records = items.Get(TASK_SITE_ID, JSON.stringify(request));
        return records && records.length > 0;
    }

    function isApplicableDate(source, todayKey) {
        if (utilities.InRange(source.DateA)) {
            const fromKey = formatDateKey(new Date(source.DateA));
            if (fromKey > todayKey) {
                return false;
            }
        }
        if (utilities.InRange(source.DateB)) {
            const toKey = formatDateKey(new Date(source.DateB));
            if (toKey < todayKey) {
                return false;
            }
        }
        return true;
    }

    function isApplicableWeekday(value, weekday) {
        const selected = parseMultipleSelections(value);
        return selected.length === 0 || selected.indexOf(weekday) >= 0;
    }

    function parseMultipleSelections(value) {
        const text = String(value || '').trim();
        if (!text) {
            return [];
        }
        try {
            const parsed = JSON.parse(text);
            if (Array.isArray(parsed)) {
                return parsed.map(function (item) {
                    return String(item);
                });
            }
        }
        catch (e) {
            context.Log('実行曜日のJSON解析に失敗しました。値=' + text);
        }
        return text.split(',').map(function (item) {
            return item.trim();
        }).filter(function (item) {
            return item !== '';
        });
    }

    function parseTime(value) {
        const match = String(value || '').trim().match(/^([01]\d|2[0-3]):([0-5]\d)$/);
        if (!match) {
            return null;
        }
        return {
            hour: Number(match[1]),
            minute: Number(match[2])
        };
    }

    function formatDateKey(date) {
        return (
            String(date.getFullYear()) +
            pad(date.getMonth() + 1) +
            pad(date.getDate())
        );
    }

    function pad(value) {
        return String(value).padStart(2, '0');
    }

    function firstOrNull(sequence) {
        if (!sequence) {
            return null;
        }
        for (const value of sequence) {
            return value;
        }
        return null;
    }
})();

(function () {
    'use strict';
    if (!columns.ClassD) return;
    const id = Number(model.IssueId);
    const status = Number(model.Status);
    const started = utilities.InRange(model.DateA);
    const ended = utilities.InRange(model.DateB);
    let html;
    if (!(id > 0)) {
        html = '<span class="task-timer-label">—</span>';
    } else if (status === 900) {
        html = '<span class="task-timer-label task-timer-done">済</span>';
    } else if (status === 910) {
        html = '<span class="task-timer-label" title="レコードを開いて再開・完了を操作してください">詳細で操作</span>';
    } else if ((status === 100 && !started && !ended) ||
               (status === 200 && started && !ended)) {
        const processId = status === 100 ? 1 : 4;
        const label = processId === 1 ? '開始' : '完了';
        const icon = processId === 1 ? '▶' : '■';
        const stamp = new Date(model.UpdatedTime).getTime();
        if (!isFinite(stamp)) {
            html = '<span class="task-timer-label">要確認</span>';
        } else {
            html = '<button type="button" class="task-timer-button task-timer-' +
                (processId === 1 ? 'start' : 'finish') + '" data-record-id="' + id +
                '" data-site-id="' + Number(context.SiteId) +
                '" data-process-id="' + processId + '" data-stamp="' + stamp +
                '" title="' + (processId === 1 ? '計測を開始します' : '計測を終了し、タスクを完了にします') +
                '"><span aria-hidden="true">' + icon + '</span> ' + label + '</button>';
        }
    } else {
        html = '<span class="task-timer-label" title="レコードを開いて状況・実績日時を確認してください">要確認</span>';
    }
    columns.ClassD.RawText = html;
})();

(function () {
    'use strict';
    // Only requests from the new grid controls. Existing editor operations are unchanged.
    const raw = String(context.ApiRequestBody || '');
    if (!raw) return;
    let request;
    try { request = JSON.parse(raw); } catch (e) { return; }
    const timer = request.TaskGridTimer;
    if (!timer) return;
    function reject(message) { context.Error(message); }
    const processId = Number(request.ProcessId);
    if (request.ProcessIds || (processId !== 1 && processId !== 4) ||
        Number(timer.SiteId) !== Number(context.SiteId)) {
        reject('一覧の計測操作が不正です。一覧を再読み込みしてください。');
        return;
    }
    const stamp = new Date(saved.UpdatedTime).getTime();
    if (!isFinite(stamp) || Number(timer.Stamp) !== stamp) {
        reject('このタスクは別の操作で更新されています。一覧を再読み込みしてください。');
        return;
    }
    const started = utilities.InRange(saved.DateA);
    const ended = utilities.InRange(saved.DateB);
    const pauseStart = utilities.InRange(saved.DateC);
    const pauseEnd = utilities.InRange(saved.DateD);
    if (processId === 1) {
        if (Number(saved.Status) !== 100 || started || ended || pauseStart || pauseEnd ||
            Number(model.Status) !== 200 || !utilities.InRange(model.DateA)) {
            reject('開始できません。レコードを開いて状況・実績日時を確認してください。');
        }
        return;
    }
    if (Number(saved.Status) !== 200 || !started || ended ||
        Number(model.Status) !== 900 || !utilities.InRange(model.DateB)) {
        reject('終了できません。レコードを開いて状況・実績日時を確認してください。');
        return;
    }
    if (pauseStart !== pauseEnd) {
        reject('中断日時が未確定です。レコードを開いて操作してください。');
        return;
    }
    const start = new Date(saved.DateA).getTime();
    const end = new Date(model.DateB).getTime();
    const from = pauseStart ? new Date(saved.DateC).getTime() : 0;
    const to = pauseEnd ? new Date(saved.DateD).getTime() : 0;
    const rest = Number(saved.NumB || 0);
    if (!isFinite(start) || !isFinite(end) || !isFinite(rest) || rest < 0 || end < start ||
        (pauseStart && (!isFinite(from) || !isFinite(to) || from < start || to < from || to > end)) ||
        end - start - (to - from) - rest * 60000 < 0) {
        reject('実績日時・休憩時間が整合しません。レコードを開いて確認してください。');
    }
})();
